// The TypeScript protocol must produce and accept exactly the bytes of the
// Rust reference implementation (vectors.json is generated by
// crates/protocol/tests/vectors.rs).

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import { fromB64, fromHex, toB64, toHex, utf8 } from "../src/protocol/bytes";
import { type Content, decode, encode } from "../src/protocol/content";
import { DIR_TO_SHARER, DIR_TO_VIEWER, FrameError, Opener, Sealer } from "../src/protocol/frame";
import { deriveKeys, prove, verifier } from "../src/protocol/keys";
import { ViewerHandshake } from "../src/protocol/noise";

const v = JSON.parse(readFileSync(new URL("./vectors.json", import.meta.url), "utf8"));
const shareId = fromB64(v.share_id, 16)!;
const secret = fromB64(v.secret, 32)!;
const challenge = fromB64(v.challenge, 32)!;

describe("keys", () => {
  it("derives link id, PSK, verifier and proofs like Rust", async () => {
    const keys = await deriveKeys(secret);
    expect(toB64(keys.linkId)).toBe(v.derived.link_id);
    expect(toHex(keys.psk)).toBe(v.derived.psk);
    expect(toB64(await verifier(keys))).toBe(v.derived.verifier);
    expect(toB64(await prove(keys, 1, shareId, challenge))).toBe(v.derived.viewer_proof);
    expect(toB64(await prove(keys, 2, shareId, challenge))).toBe(v.derived.owner_proof);
  });

  it("rejects malformed base64url", () => {
    expect(fromB64("AQL-_w", 4)).toEqual(new Uint8Array([1, 2, 254, 255]));
    expect(fromB64("AQL+/w", 4)).toBeNull();
    expect(fromB64("AQL-", 4)).toBeNull();
  });
});

describe("noise", () => {
  it("builds message 1 and reads message 2 like snow", async () => {
    const keys = await deriveKeys(secret);
    const [hs, msg1] = await ViewerHandshake.start(
      shareId,
      keys.psk,
      utf8(v.noise.msg1_payload),
      fromHex(v.noise.viewer_ephemeral),
    );
    expect(toHex(msg1)).toBe(v.noise.msg1);
    const [session, payload] = await hs.finish(fromHex(v.noise.msg2));
    expect(new TextDecoder().decode(payload)).toBe(v.noise.msg2_payload);
    expect(toHex(session.toSharer)).toBe(v.noise.to_sharer);
    expect(toHex(session.toViewer)).toBe(v.noise.to_viewer);
  });

  it("fails on a tampered message 2", async () => {
    const keys = await deriveKeys(secret);
    const [hs] = await ViewerHandshake.start(
      shareId,
      keys.psk,
      utf8(v.noise.msg1_payload),
      fromHex(v.noise.viewer_ephemeral),
    );
    const msg2 = fromHex(v.noise.msg2);
    msg2[msg2.length - 1]! ^= 1;
    await expect(hs.finish(msg2)).rejects.toThrow("handshake authentication failed");
  });
});

describe("frames", () => {
  const binding = (direction: number) => ({ shareId, viewerId: v.frames.viewer_id, direction });

  it("opens Rust frames in order and drops replays", async () => {
    const opener = await Opener.create(fromHex(v.noise.to_viewer), binding(DIR_TO_VIEWER));
    const [f1, f2] = v.frames.to_viewer;
    expect(toHex(await opener.open(fromHex(f1.frame)))).toBe(f1.plaintext);
    expect(toHex(await opener.open(fromHex(f2.frame)))).toBe(f2.plaintext);
    await expect(opener.open(fromHex(f1.frame))).rejects.toEqual(new FrameError("replay"));
    await expect(opener.open(fromHex(f2.frame))).rejects.toEqual(new FrameError("replay"));
  });

  it("seals input exactly like Rust", async () => {
    const sealer = await Sealer.create(fromHex(v.noise.to_sharer), binding(DIR_TO_SHARER));
    const [f] = v.frames.to_sharer;
    expect(toHex(await sealer.seal(fromHex(f.plaintext)))).toBe(f.frame);
  });

  it("rejects a frame bound to another viewer or direction", async () => {
    const [f1] = v.frames.to_viewer;
    const other = await Opener.create(fromHex(v.noise.to_viewer), {
      shareId,
      viewerId: 8,
      direction: DIR_TO_VIEWER,
    });
    await expect(other.open(fromHex(f1.frame))).rejects.toEqual(new FrameError("auth"));
    const wrongDir = await Opener.create(fromHex(v.noise.to_viewer), binding(DIR_TO_SHARER));
    await expect(wrongDir.open(fromHex(f1.frame))).rejects.toEqual(new FrameError("auth"));
  });
});

describe("content", () => {
  const cases: Record<string, Content> = {
    output: { t: "output", seq: 258n, data: utf8("ab") },
    snapshot: {
      t: "snapshot",
      coversSeq: 257n,
      cols: 80,
      rows: 24,
      part: "screen",
      index: 1,
      count: 3,
      compressed: true,
      data: new Uint8Array([0xde, 0xad]),
    },
    status: { t: "status", status: { input_paused: true } },
    size: { t: "size", cols: 300, rows: 50 },
    input: { t: "input", data: new Uint8Array([3]) },
    resync_some: { t: "resync", lastSeq: 9n },
    resync_none: { t: "resync", lastSeq: null },
  };
  for (const [name, content] of Object.entries(cases)) {
    it(`${name} matches the Rust encoding both ways`, () => {
      expect(toHex(encode(content))).toBe(v.content[name]);
      expect(decode(fromHex(v.content[name]))).toEqual(content);
    });
  }

  it("rejects truncated and unknown content", () => {
    expect(() => decode(new Uint8Array([0x10, 1]))).toThrow();
    expect(() => decode(new Uint8Array([0x7f]))).toThrow();
  });
});

describe("snapshot inflate", () => {
  it("inflates raw DEFLATE produced by Rust", async () => {
    const { inflateRaw } = await import("../src/engine");
    expect(toHex(await inflateRaw(fromHex(v.deflate.compressed)))).toBe(v.deflate.raw);
  });

  it("refuses a chunk that inflates past the limit", async () => {
    const { inflateRaw } = await import("../src/engine");
    const big = new Uint8Array(1024 * 1024);
    const compressed = new Uint8Array(
      await new Response(new Blob([big]).stream().pipeThrough(new CompressionStream("deflate-raw"))).arrayBuffer(),
    );
    await expect(inflateRaw(compressed)).rejects.toThrow("snapshot chunk too large");
  });
});

describe("deep link", () => {
  it("matches the Rust deep link", async () => {
    const { deepLink } = await import("../src/protocol/link");
    expect(deepLink(v.relay_url, v.share_id, v.secret)).toBe(v.deep_link);
    expect(deepLink(`${v.relay_url}/`, v.share_id, v.secret)).toBe(v.deep_link);
  });

  it("needs a TLS relay with a plain host", async () => {
    const { deepLink } = await import("../src/protocol/link");
    expect(deepLink("ws://relay.example", v.share_id, v.secret)).toBeNull();
    expect(deepLink("wss://relay.example/path", v.share_id, v.secret)).toBeNull();
    expect(deepLink("wss://", v.share_id, v.secret)).toBeNull();
  });
});
